dtsPropsFor.EmptyState:
/** Lucide icon component, rendered at 40px in --muted. */
icon: React.ComponentType<{ size?: number | string; color?: string; strokeWidth?: number | string }>;
/** One line, sentence case, states the absence: "No datasets yet". */
title: string;
/** Optional second line explaining what would fill this space. */
description?: string;
/** Primary button for the next action, when there is one worth naming. */
action?: React.ReactNode;

dtsPropsFor.IconLabel:
/** Lucide icon component. Rendered aria-hidden at strokeWidth 1.9. */
icon: React.ComponentType<{ size?: number | string; color?: string; strokeWidth?: number | string }>;
/** The label text. Stays a plain child so screen readers and getByRole read it. */
children?: React.ReactNode;
/** Icon size in px. Default 13. */
size?: number;

dtsPropsFor.LoadError:
/** What failed to load, in the user's words: "reports", "the lineage graph". */
what: string;
/** The caught error. An axios error's response.data.detail or an Error's message is shown when present. */
error?: unknown;
/** When given, renders a "Try again" button. */
onRetry?: () => void;
